-- ShopSphere e-commerce practice database (MySQL 8.0+)
-- DROP DATABASE IF EXISTS shopsphere;
CREATE DATABASE shopsphere;
USE shopsphere;

CREATE TABLE regions (region_id INT PRIMARY KEY, region_name VARCHAR(50) NOT NULL);
CREATE TABLE employees (employee_id INT PRIMARY KEY, first_name VARCHAR(50), last_name VARCHAR(50), department VARCHAR(50), job_title VARCHAR(80), manager_id INT NULL, hire_date DATE, salary DECIMAL(10,2), region_id INT,
  FOREIGN KEY (manager_id) REFERENCES employees(employee_id), FOREIGN KEY (region_id) REFERENCES regions(region_id));
CREATE TABLE customers (customer_id INT PRIMARY KEY, first_name VARCHAR(50), last_name VARCHAR(50), email VARCHAR(120), phone VARCHAR(30), gender CHAR(1), birth_date DATE, city VARCHAR(60), country VARCHAR(60), region_id INT, signup_date DATE, acquisition_channel VARCHAR(30), is_premium TINYINT(1) DEFAULT 0,
  FOREIGN KEY (region_id) REFERENCES regions(region_id));
CREATE TABLE categories (category_id INT PRIMARY KEY, category_name VARCHAR(60), parent_category_id INT NULL, FOREIGN KEY (parent_category_id) REFERENCES categories(category_id));
CREATE TABLE suppliers (supplier_id INT PRIMARY KEY, supplier_name VARCHAR(100), country VARCHAR(60), rating DECIMAL(2,1));
CREATE TABLE products (product_id INT PRIMARY KEY, product_name VARCHAR(120), category_id INT, supplier_id INT, unit_price DECIMAL(10,2), unit_cost DECIMAL(10,2), stock_quantity INT, launch_date DATE, is_active TINYINT(1),
  FOREIGN KEY (category_id) REFERENCES categories(category_id), FOREIGN KEY (supplier_id) REFERENCES suppliers(supplier_id));
CREATE TABLE orders (order_id INT PRIMARY KEY, customer_id INT, order_date DATETIME, status VARCHAR(20), shipping_city VARCHAR(60), shipping_country VARCHAR(60), shipping_cost DECIMAL(8,2), discount_code VARCHAR(20) NULL, sales_rep_id INT NULL, delivered_date DATE NULL,
  FOREIGN KEY (customer_id) REFERENCES customers(customer_id), FOREIGN KEY (sales_rep_id) REFERENCES employees(employee_id));
CREATE TABLE order_items (order_item_id INT PRIMARY KEY, order_id INT, product_id INT, quantity INT, unit_price DECIMAL(10,2), discount_pct DECIMAL(4,2),
  FOREIGN KEY (order_id) REFERENCES orders(order_id), FOREIGN KEY (product_id) REFERENCES products(product_id));
CREATE TABLE payments (payment_id INT PRIMARY KEY, order_id INT, payment_date DATETIME, payment_method VARCHAR(20), amount DECIMAL(10,2), payment_status VARCHAR(20),
  FOREIGN KEY (order_id) REFERENCES orders(order_id));
CREATE TABLE returns (return_id INT PRIMARY KEY, order_item_id INT, return_date DATE, reason VARCHAR(60), refund_amount DECIMAL(10,2),
  FOREIGN KEY (order_item_id) REFERENCES order_items(order_item_id));
CREATE TABLE reviews (review_id INT PRIMARY KEY, product_id INT, customer_id INT, rating INT, review_date DATE, review_text VARCHAR(255),
  FOREIGN KEY (product_id) REFERENCES products(product_id), FOREIGN KEY (customer_id) REFERENCES customers(customer_id));
CREATE TABLE web_events (event_id INT PRIMARY KEY, session_id VARCHAR(20), customer_id INT NULL, event_time DATETIME, event_type VARCHAR(30), page VARCHAR(60), device VARCHAR(20), traffic_source VARCHAR(30), product_id INT NULL);
CREATE TABLE marketing_spend (spend_id INT PRIMARY KEY, spend_month DATE, channel VARCHAR(30), region_id INT, amount DECIMAL(10,2), FOREIGN KEY (region_id) REFERENCES regions(region_id));


-- Quick check
SELECT 'customers' t, COUNT(*) FROM customers UNION ALL SELECT 'products',COUNT(*) FROM products UNION ALL SELECT 'orders',COUNT(*) FROM orders UNION ALL SELECT 'order_items',COUNT(*) FROM order_items UNION ALL SELECT 'payments',COUNT(*) FROM payments UNION ALL SELECT 'web_events',COUNT(*) FROM web_events;